"""Builds the Flags / OPEN / notes text for reports/PILOT_SEED0.md from the run files (every number read from a file) -> out/pilot_report_extras.json"""
import json
from pathlib import Path
import numpy as np
M = Path("{working_folder}"); R = Path("{experiment_store}/runs/pilot_seed0")
F = json.load(open(M / "out/pilot_final.json")); comp = F["comparison"]; recs = {a: json.load(open(R / a / "run.json")) for a in ("carry", "wiped")}
ch = {a: next(c for c in recs[a]["checks"] if c["progress"] == recs[a]["chosen"]["progress"]) for a in recs}
ev = json.load(open(M / "out/pilot_event_subset.json")); z = comp["carry_memory_zeroed"]
c, w = ch["carry"], ch["wiped"]
gc = c["slots"]["gate_mean_per_slot"]; gw = w["slots"]["gate_mean_per_slot"]
curve_c = recs["carry"]["checks"]; curve_w = recs["wiped"]["checks"]
n_fail_c = sum(1 for x in curve_c[1:] if not x["gate_ok"]); n_fail_w = sum(1 for x in curve_w[1:] if not x["gate_ok"])
ade_over_c = sum(1 for x in curve_c[1:] if x["closest_of_32_ade3_all"] > 0.258); ade_over_w = sum(1 for x in curve_w[1:] if x["closest_of_32_ade3_all"] > 0.258)
st_c = recs["carry"]["steps"]; st_w = recs["wiped"]["steps"]
FL = [
 f"**Carry arm crashed once and was resumed.** At 04:54 IST its pass-1.216 check hit 0.1.8b's check assertion \"pick is not the argmax of the last logit\" (`logs/pilot_carry_part1_crashed_p1.2_check.log`): the model's pick is argmax(sigmoid(last logit)) (`drive_jepa_model.py:85, 90`) and two logits so large that sigmoid rounds both to 1.0 in fp32 make the two argmaxes differ. The check now counts such saturated ties instead of aborting (`s6_train.safety_tolerant`, the imported function with that one line changed; verified identical on a clean dump) and records the largest last logit. Carry was resumed at 19:19 IST from `resume.pt` (pass 1.0, step 4,288; `run.json: resumes`), so the ≈ 930 pass-2 steps before the crash were trained again from the pass-1.0 weights, with the same batch order (seeded plan) but different numerics (atomic adds in the deformable attention, BUILD3 flag 6; the vocabulary-term draws also restart). In the resumed trajectory **no check showed a saturated tie** (largest last logit {max(x['logit_saturation']['max_last_logit'] for x in curve_c if x.get('logit_saturation')):.1f}; `run.json: checks[*].logit_saturation`); the saturated check's dump of the crashed trajectory was not saved. Wall time of the carry arm includes the 14.4 h gap between the crash and the resume (04:54–19:19).",
 f"**Carry's 16 slots never differentiate and its gate is almost closed at the chosen check.** Mean pairwise cosine between the slots of the memory read at in_picking moments after the warm-up: {c['slots']['cos_read_mean']:.4f} (written: {c['slots']['cos_new_mean']:.4f}); untrained it was 0.9995. The gate mean per slot at the chosen check is {np.mean(gc):.3f} (all 16 within {min(gc):.3f}–{max(gc):.3f}), i.e. M_new ≈ 0.994 · M_old: after the first moments the memory barely changes (mean ‖M read‖ {c['slots']['M_read_norm_mean']:.1f}). The wiped arm's gate sits at {np.mean(gw):.3f} (its memory is zeroed before every moment, so its update is never read). Memory-use norms grow steadily in both arms (generator read output projection {c['memory_use']['generator_read_out_proj_weight_norm']:.3f} carry vs {w['memory_use']['generator_read_out_proj_weight_norm']:.3f} wiped; rating-head new columns {c['memory_use']['rating_head_new_columns_norm']:.2f} vs {w['memory_use']['rating_head_new_columns_norm']:.2f}), so both arms use the memory path, the wiped arm as a constant input. The zero-memory diagnostic (step 5) is the direct test; OPEN 2.",
 f"**Event subset: {ev['in_picking_graded_event_moments']} graded moments from {ev['event_clips_in_picking']} clips, and 0.1.8b already grades it at {recs['carry']['checks'][0]['event']['pick_grade_event']:.3f} at step 0.** Too small to read (pre-registered caveat) and near the ceiling: the event gap ({comp['event']['gap']:+.4f}) moves by ±0.03 between neighbouring checks in both arms (`run.json: checks[*].event.pick_grade_event`). The 34 raw picking clips have no tracks (`out/pilot_picking_clip_sources.csv`), so only ego-only events could have been found on them; none were.",
 f"**Safety gates were the binding constraint, not the pick grade.** Of the trained checks, carry failed the choice gates (hard-brake picks = 0 and pull-away go ≥ 0.66) at {n_fail_c} of 10 and wiped at {n_fail_w} of 10; the closest-of-32 ADE (3 s) exceeded the pre-registered +0.02 m tolerance at {ade_over_c} carry and {ade_over_w} wiped checks (`run.json: checks`). The arm's choice rule (as written by Sid) uses the two gates; the pre-registered comparison adds the ADE tolerance; both chosen checks pass all three. The pull-away go rate swings between 0.52 and 0.89 from check to check (106 standstill moments), the same go/stay swing as 0.1.8b attempt 2 (`generator-joint-pai-s8` report).",
 f"**Pick grades went DOWN before they went up.** Both arms fell below 0.1.8b's 0.7685 for most of pass 1 (carry 0.7526 → 0.7500 → 0.7656 → 0.7611 → 0.7699; wiped 0.7563 → 0.7481 ×3 → 0.7595) and peaked at pass 1.216 (carry 0.7752, wiped 0.7639), then fell again by pass 2.0 (0.7449 / 0.7368 with failed gates). The chosen checks are single peaks on noisy curves; the clip-clustered bootstrap intervals in step 5 give the width.",
 f"**Wall time and throughput.** Steps averaged {np.mean([s['step_s'] for s in st_c]):.2f} s (carry) / {np.mean([s['step_s'] for s in st_w]):.2f} s (wiped) against 1.65 s alone in build 3: the two arms shared the GPU with other users' jobs at 90–100 % utilisation all night (`logs/pilot_chain.log`), grading wait {np.mean([s['grade_wait_s'] for s in st_c]):.2f} s, data wait {np.mean([s['data_wait_s'] for s in st_c]):.3f} s. A pass took ≈ 4 h with its 5 checks (≈ 10 min each). Wiped: 8.2 h for 2 passes; carry: 23.5 h wall including the crash gap.",
 "**Four launches before the run** (`logs/pilot_chain.log`): 23:09 import-order crash (the older `pai_train` copy imported first, fixed by importing the trainer module first); 23:10 a 3-pass launch stopped by hand inside its step-0 check when Sid's amended 2-pass brief arrived (its 22 orphaned grading workers killed); 23:20 refused by the memory gate (5-min load 32.9, inflated by the kill/relaunch churn); 23:51 the run. Nothing from the stopped launch was kept.",
 "**BUILD3 flag 12's date was wrong**: the idle processes started 2026-11-08 00:24–00:25 (the batch-8 cache attempt's loader workers), not 2026-11-07; a second, larger group (10 grading workers, ≈ 1 GB each) came from build 3's standalone routing test on 2026-11-09 22:18. All 20 were mine, orphaned (parent pid 1), idle; killed (step 0). The leak is closed in `s6_tests.py`.",
 f"**Carry with memory zeroed, as measured:** pick grade {z['pick_grade']:.4f} vs the carry model's own {z['carry_own_pick_grade']:.4f} (drop {z['drop']:+.4f}); event {z['event_pick_grade']:.4f}; gates {'pass' if z['gates']['pass'] else 'FAIL'} (hard {z['gates']['hard_picks_above10']}, go {100 * z['gates']['go_rate_pull_away']:.1f} %, ADE {z['gates']['closest_of_32_ade3']:.3f} m). " + ("The drop exceeds 0.002: the carry model relies on its memory." if z["relies_on_memory"] else ("Within 0.002: the carry model ignores its memory (CLOSE flag by the rule)." if z["within_0.002"] else "The pick grade is HIGHER with the memory zeroed: the carried memory hurts the pick; the model would do better as its own wiped arm.")),
 "**Status-script ETA was noisy** (it used the last 100-step line's step time); the chain log and `run.json` carry the real times.",
]
OP = [
 "**What next, given the verdict.** " + ("Recommend: GO as pre-registered: read both held-out slices once (carry, wiped, 0.1.8b), then the memory switch in the AlpaSim adapter, then closed loop on the 12 diagnosis scenes. Alternative: add seeds 1 and 2 first (≈ 8 h per arm, in parallel) to see whether the overall gap survives." if comp["go"] else
   f"Recommend: STOP as pre-registered and review: the event gap ({comp['event']['gap']:+.4f} on 34 moments) fails the +0.01 rule while the overall gap is {comp['overall']['gap']:+.4f}; the event subset cannot carry a rule (flag 3). Alternative: re-register with the overall gap and the zero-memory test as the rule and the event subset as information, then decide on seeds 1 and 2; or run seeds 1 and 2 now under the current rule."),
 f"**The memory is single-slot and nearly frozen in carry (flag 2).** Recommend: before any further seed, change the update so that writing is forced early (e.g. gate bias initialised open, g ≈ 0.9, and a per-slot embedding also on the keys/values of the reads), and re-run the build-3 tests; cost ≈ 1 h of tests. Alternative: keep the design as is and let seeds 1 and 2 decide; the zero-memory test ({z['drop']:+.4f}) says how much the carried state matters today.",
 "**Choice gates vs comparison gates.** The arm's choice used hard-brake = 0 and pull-away go ≥ 0.66 (Sid's rule); the pre-registered safety gates add the ADE (3 s) tolerance. Recommend: add the ADE tolerance to the choice rule in any further run so a chosen check cannot fail the comparison. Alternative: keep them apart (as now) and report both.",
 "**Resumed trajectory.** The carry arm's pass-2 segment was retrained after the crash (flag 1), so its curve is one trajectory with a restart, not the uninterrupted run. Recommend: accept (same batch order; the chosen check is in the resumed segment and is fully measured). Alternative: re-run carry from scratch (≈ 8 h) for a clean single trajectory.",
 "**Logit saturation in the check.** Recommend: keep the tolerant check (counts ties, keeps the model's actual pick, records the largest last logit at every check). Alternative: restore the assertion and treat a tie as a failed check.",
 "**Event subset.** Recommend: for any further pilot, define the event subset on the graded held-out slice (355 reconstructed clips with clipgt tracks, 3.55 % event moments ≈ 370 moments) rather than the picking set; it is read once at the end either way. Alternative: enlarge the picking set's event share by adding reconstructed val clips with events to the picking clips (a new frozen set).",
]
CN = (f"Curves: both arms dip below 0.1.8b in pass 1 and peak at pass 1.216; carry's slot cosine stays at 0.9992–1.0000 at every check (one slot in effect), its gate mean per slot falls from 0.5 (untrained) to {np.mean(gc):.3f} at the chosen check; "
      f"memory-use norms rise monotonically in both arms. Carry checks with a failed gate: {n_fail_c} of 10; wiped: {n_fail_w} of 10.")
json.dump({"FLAGS": "\n".join(f"{i + 1}. {t}" for i, t in enumerate(FL)), "OPEN": "\n".join(f"{i + 1}. {t}" for i, t in enumerate(OP)), "CURVE_NOTE": CN, "GPU_LAUNCH": "76.0 GB"},
          open(M / "out/pilot_report_extras.json", "w"), indent=1)
print("extras written; verdict", comp["verdict"])
